CREATE OR REPLACE FUNCTION public.request_service(_service text,_area text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; who record; caller uuid:=auth.uid(); BEGIN IF caller IS NULL OR NOT public.account_allowed(caller) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF NOT public.has_paid_bell(caller) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; IF length(trim(public.service_occupation(_service))) NOT BETWEEN 2 AND 40 OR length(trim(_area)) NOT BETWEEN 1 AND 80 THEN RAISE EXCEPTION 'SERVICE_AREA_REQUIRED'; END IF; PERFORM 1 FROM public.profiles WHERE id=caller FOR UPDATE; SELECT id INTO rid FROM public.service_requests WHERE user_id=caller AND service=public.service_occupation(_service) AND lower(trim(area))=lower(trim(_area)) AND created_at>now()-interval '5 minutes' LIMIT 1; IF rid IS NOT NULL THEN RETURN rid; END IF; INSERT INTO public.service_requests(user_id,service,area) VALUES(caller,public.service_occupation(_service),trim(_area)) RETURNING id INTO rid; FOR who IN SELECT user_id FROM public.service_profiles WHERE published AND public.service_occupation(coalesce(nullif(category,''),service))=public.service_occupation(_service) AND lower(trim(town))=lower(trim(_area)) UNION SELECT user_id FROM public.posts WHERE module='job' AND service_type='service' AND kind='employer' AND status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) AND public.service_occupation(skill)=public.service_occupation(_service) AND lower(trim(location))=lower(trim(_area)) LOOP IF who.user_id<>caller AND public.has_paid_bell(who.user_id) AND public.account_allowed(who.user_id) THEN PERFORM 1 FROM public.profiles WHERE id=who.user_id FOR UPDATE; INSERT INTO public.notifications(user_id,message) VALUES(who.user_id,'మీ ప్రాంతంలో మీ సేవ కోరారు; సేవల అభ్యర్థనల పేజీలో చూడండి.'); END IF; END LOOP; RETURN rid; END $$;